"use strict";
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const { spawnSync } = require("node:child_process");
const { createRequire } = require("node:module");
const yaml = createRequire(path.resolve(__dirname, "../../../../eng/common/scripts/eval/package.json"))("yaml");
const skillRoot = path.resolve(__dirname, "..");
const repoRoot = path.resolve(__dirname, "../../../..");
const workflow = fs.readFileSync(path.join(repoRoot, ".github/workflows/sdk-build-repair.md"), "utf8");
const source = yaml.parse(/^---\r?\n([\s\S]*?)\r?\n---/.exec(workflow)[1]);
const lock = yaml.parse(fs.readFileSync(path.join(repoRoot, ".github/workflows/sdk-build-repair.lock.yml"), "utf8"));
const success = { success: true, attemptsUsed: 1, operation_status: "Succeeded" };
const failed = { success: false, attemptsUsed: 2, errorCode: "BuildAfterPatchesFailed",
  buildResult: "error CS1061: CustomCode member missing", operation_status: "Failed" };
const slash = (value) => value.replace(/\\/g, "/");
const quote = (value) => "'" + value.replace(/'/g, "''") + "'";
function run(command, args, options = {}) {
  const result = spawnSync(command, args, { encoding: "utf8", timeout: 30000, ...options });
  assert.ifError(result.error);
  return result;
}
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "repair-infra-"));
  t.after(() => fs.rmSync(root, { recursive: true, force: true }));
  const results = path.join(root, "results");
  fs.mkdirSync(results);
  const outputFile = path.join(root, "agent_output.json");
  const original = { items: [{ type: "report_incomplete", reason: "Baseline restore HTTP401" },
    { type: "push_to_pull_request_branch" }], errors: [] };
  fs.writeFileSync(outputFile, JSON.stringify(original));
  fs.writeFileSync(path.join(results, "context.json"), JSON.stringify({
    PackagePath: "sdk/contoso/Azure.Contoso.Widgets", PreRepairSha: "a".repeat(40),
  }));
  const write = (name, value) => fs.writeFileSync(path.join(results, name), value);
  function recover(agentOutcome = "success") {
    return run("pwsh", ["-NoProfile", "-File", path.join(skillRoot, "complete-repair-report.ps1"),
      "-AgentOutputFile", outputFile, "-ResultsDir", results, "-Pr", "123",
      "-HeadSha", "a".repeat(40), "-Repo", "Azure/azure-sdk-for-net",
      "-RepoRoot", root, "-AgentOutcome", agentOutcome], {
      env: { ...process.env, AZSDK_REPAIR_RESULTS_DIR: results },
    });
  }
  function complete(agentOutcome = "success") {
    const result = recover(agentOutcome);
    assert.equal(result.status, 0, result.stdout + result.stderr);
    const output = JSON.parse(fs.readFileSync(outputFile, "utf8"));
    assert.deepEqual(output.items.map((item) => item.type), ["add_comment"]);
    assert.deepEqual(output.errors, []);
    const body = output.items[0].body;
    assert.match(body, /--generated by Copilot/);
    const telemetry = JSON.parse(/```json\n([\s\S]*?)\n```/.exec(body)[1]);
    return { output, body, telemetry };
  }
  function engine(response, exitCode = response.success ? 0 : 1, stderr = "") {
    write("engine-command.txt", "azsdk -o json tsp client customized-update --edit-scope CustomCode --max-attempts 3");
    write("engine-stdout.txt", JSON.stringify(response));
    write("engine-stderr.txt", stderr);
    write("engine-exit-code.txt", String(exitCode));
  }
  return { root, results, outputFile, original, write, recover, complete, engine };
}

test("install and selection are exact, isolated and inherited by the sandbox", (t) => {
  assert.equal(source.runtimes?.dotnet, undefined);
  const install = source.steps.find((step) => step.name === "Install approved .NET SDK");
  assert.equal(install.with["global-json-file"], "global.json");
  assert.equal(install.with["dotnet-version"], undefined);
  const f = fixture(t);
  const setup = source.steps.find((step) => step.name === "Configure isolated .NET installation");
  const setupFile = path.join(f.root, "setup.ps1");
  fs.writeFileSync(setupFile, setup.run);
  const envFile = path.join(f.root, "environment");
  const setupResult = run("pwsh", ["-NoProfile", "-File", setupFile], {
    env: { ...process.env, RUNNER_TOOL_CACHE: f.root, GITHUB_RUN_ID: "123", GITHUB_RUN_ATTEMPT: "2", GITHUB_ENV: envFile },
  });
  assert.equal(setupResult.status, 0, setupResult.stderr);
  const env = Object.fromEntries(fs.readFileSync(envFile, "utf8").trim().split(/\r?\n/).map((line) => line.split("=")));
  assert.match(slash(env.DOTNET_ROOT), /repair-dotnet\/123-2\/bin$/);
  assert.equal(env.DOTNET_INSTALL_DIR, env.DOTNET_ROOT);
  assert.equal(env.DOTNET_HOST_PATH, env.DOTNET_ROOT + "/dotnet");
  assert.equal(env.DOTNET_MULTILEVEL_LOOKUP, "0");
  assert.equal(lock.jobs.agent.steps.find((step) => step.name === setup.name).run, setup.run);
  assert.match(workflow, /export PATH="\$DOTNET_ROOT:\$PATH"/);
  const lockedInstall = lock.jobs.agent.steps.find((step) => step.name === install.name);
  assert.equal(lockedInstall.with["global-json-file"], "global.json");
  assert.equal(lock.jobs.agent.steps.filter((step) => /setup-dotnet@/.test(step.uses || "")).length, 1);
});

test("recovery runs before the existing native handler without weakening original validation", () => {
  const steps = lock.jobs.safe_outputs.steps;
  const recovery = steps.findIndex((step) => step.name === "Complete terminal repair report");
  const publisher = steps.findIndex((step) => step.id === "process_safe_outputs");
  assert(recovery >= 0 && publisher > recovery);
  assert.equal(lock.jobs.safe_outputs.if, "(!cancelled()) && needs.agent.result != 'skipped' && needs.detection.result == 'success'");
  assert.equal(lock.jobs.safe_outputs["runs-on"], "ubuntu-latest");
  assert.equal(lock.jobs.agent.permissions.contents, "read");
  assert.equal(lock.jobs.agent.permissions["pull-requests"], "read");
  assert.equal(source["safe-outputs"]["add-comment"].max, 1);
  const upload = steps.find((step) => step.name === "Upload recovered repair report");
  assert.equal(upload.with.name, "repair-report");
  const validation = lock.jobs.validate_agent_output.steps.find((step) => step.id === "validate");
  assert.match(validation.with.script, /report_incomplete/);
  assert(!lock.jobs.validate_agent_output.needs.includes("safe_outputs"));
});

for (const [name, selected, buildExit, expected, error] of [
  ["restore401", "10.0.401", 1, 1, "error NU1301: HTTP401 restoring Microsoft.NET.ILLink.Tasks.10.0.13"],
  ["green", "10.0.401", 0, 0, "Build succeeded."],
  ["custom-code", "10.0.401", 1, 1, "error CS1061: missing custom member"],
  ["wrong-sdk", "10.0.402", 0, 1, "Build succeeded."],
]) {
  test(`baseline captures ${name} with a newer default SDK present and never invokes the engine`, (t) => {
    const f = fixture(t);
    const packagePath = "sdk/contoso/Azure.Contoso.Widgets";
    const src = path.join(f.root, packagePath, "src");
    fs.mkdirSync(src, { recursive: true });
    fs.writeFileSync(path.join(src, "Azure.Contoso.Widgets.csproj"), "<Project />");
    fs.writeFileSync(path.join(f.root, "global.json"), JSON.stringify({ sdk: { version: "10.0.401", rollForward: "feature" } }));
    const results = path.join(f.root, "baseline");
    const approved = path.join(f.root, "approved");
    fs.mkdirSync(approved);
    const fakeHost = path.join(approved, "dotnet.ps1");
    fs.writeFileSync(fakeHost, `
if ($args[0] -eq '--version') { '${selected}'; $global:LASTEXITCODE = 0; return }
if ($args[0] -ne 'build') { throw 'Unexpected dotnet call' }
@{ Command = $args; Root = $env:DOTNET_ROOT; Path = $env:PATH } | ConvertTo-Json |
  Set-Content -LiteralPath ${quote(path.join(f.root, "build-call.json"))}
'${error}'
$global:LASTEXITCODE = ${buildExit}
`);
    // Substitute only the executable boundary; run all baseline orchestration.
    const wrapper = path.join(f.root, "baseline.ps1");
    fs.writeFileSync(wrapper, `
function global:git { if ("$args" -cne 'rev-parse HEAD') { throw 'Unexpected git call' }; '${"a".repeat(40)}'; $global:LASTEXITCODE = 0 }
function global:Join-Path {
  param([string]$Path, [string]$ChildPath)
  if ($Path -eq $env:DOTNET_ROOT -and $ChildPath -in @('dotnet', 'dotnet.exe')) { return ${quote(fakeHost)} }
  Microsoft.PowerShell.Management\\Join-Path -Path $Path -ChildPath $ChildPath
}
& ${quote(path.join(skillRoot, "invoke-repair-baseline.ps1"))} -RepoRoot ${quote(f.root)} `
      + `-PackagePath '${packagePath}' -ResultsDir ${quote(results)}\nexit $LASTEXITCODE\n`);
    const result = run("pwsh", ["-NoProfile", "-File", wrapper], { env: {
      ...process.env, DOTNET_ROOT: approved, PATH: "newer-default-sdk" + path.delimiter + process.env.PATH,
    } });
    assert.equal(result.status, expected, result.stderr);
    assert.equal(fs.readFileSync(path.join(results, "baseline-exit-code.txt"), "utf8").trim(), String(expected));
    const context = JSON.parse(fs.readFileSync(path.join(results, "context.json"), "utf8"));
    assert.equal(context.PackagePath, packagePath);
    assert.equal(context.PreRepairSha, "a".repeat(40));
    const errors = fs.readFileSync(path.join(results, "pre-repair-errors.txt"), "utf8");
    if (name === "wrong-sdk") {
      assert.match(errors, /Expected SDK 10\.0\.401.*10\.0\.402/);
      assert.equal(fs.existsSync(path.join(f.root, "build-call.json")), false);
    } else {
      assert.match(errors, new RegExp(error.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")));
      const call = JSON.parse(fs.readFileSync(path.join(f.root, "build-call.json"), "utf8"));
      assert.equal(call.Root, approved);
      assert(call.Path.startsWith(approved + path.delimiter));
      assert.deepEqual(call.Command, ["build", path.join(src, "Azure.Contoso.Widgets.csproj")]);
    }
    assert.equal(fs.existsSync(path.join(results, "result.json")), false);
    assert.equal(fs.existsSync(path.join(results, "engine-command.txt")), false);
    if (name === "restore401") {
      for (const file of fs.readdirSync(results)) {
        fs.copyFileSync(path.join(results, file), path.join(f.results, file));
      }
      const report = f.complete();
      assert.equal(report.telemetry.status, "failed");
      assert.match(report.body, /NU1301.*HTTP401/);
      assert.equal(fs.existsSync(path.join(f.results, "result.json")), false);
      assert.equal(fs.existsSync(path.join(f.results, "engine-command.txt")), false);
    }
  });
}

test("nested engine validation resolves approved dotnet instead of a newer SDK first on PATH", (t) => {
  const f = fixture(t);
  const approved = path.join(f.root, "approved");
  const newer = path.join(f.root, "newer");
  for (const [dir, version] of [[approved, "10.0.401"], [newer, "10.0.402"]]) {
    fs.mkdirSync(dir);
    fs.writeFileSync(path.join(dir, "dotnet"), `#!/bin/bash\nprintf '%s\\n' '${version}'\n`, { mode: 0o755 });
  }
  const invocation = /```bash\r?\n(export PATH="\$DOTNET_ROOT:\$PATH"[\s\S]*?)```/.exec(workflow)[1]
    .replaceAll("<maxIterations from repair-config.yml>", "3");
  const fakeEngine = `
azsdk() {
  if [[ "$*" == *--help ]]; then echo --max-attempts; return; fi
  /bin/bash -c 'dotnet --version' > "$RUNNER_TEMP/nested-version"
  echo '{"success":true,"attemptsUsed":1}'
}
`;
  const setupPath = process.platform === "win32"
    ? 'export DOTNET_ROOT="$(cygpath -u "$DOTNET_ROOT")"\nexport PATH="$(cygpath -u "$TEST_NEWER_ROOT"):$PATH"\n'
    : 'export PATH="$TEST_NEWER_ROOT:$PATH"\n';
  const result = run(process.env.BASH || "bash", ["--noprofile", "--norc", "-c", setupPath + fakeEngine + invocation], {
    env: { ...process.env, DOTNET_ROOT: slash(approved), DOTNET_HOST_PATH: slash(path.join(approved, "dotnet")),
      TEST_NEWER_ROOT: slash(newer), AZSDK_REPAIR_RESULTS_DIR: slash(f.results),
      RUNNER_TEMP: slash(f.root), GITHUB_WORKSPACE: slash(repoRoot) },
  });
  assert.equal(result.status, 0, result.stderr);
  assert.equal(fs.readFileSync(path.join(f.root, "nested-version"), "utf8").trim(), "10.0.401");
});

test("baseline restore401 produces deterministic failed/NoEngineResult add_comment only", (t) => {
  const f = fixture(t);
  f.write("baseline-exit-code.txt", "1");
  f.write("pre-repair-errors.txt", "error NU1301: HTTP401 retrieving Microsoft.NET.ILLink.Tasks.10.0.13 from the controlled feed");
  const originalBytes = fs.readFileSync(f.outputFile, "utf8");
  const { body, telemetry } = f.complete();
  assert.equal(telemetry.status, "failed");
  assert.match(body, /\*\*Stop reason\*\* \| `NoEngineResult`/);
  assert.match(body, /HTTP401.*Microsoft.NET.ILLink.Tasks.10.0.13/);
  assert.match(body, /changes are not eligible for publication/);
  assert.equal(fs.existsSync(path.join(f.results, "result.json")), false);
  assert.equal(fs.existsSync(path.join(f.results, "engine-command.txt")), false);
  // The validator downloads the original artifact, not the mutated local copy.
  assert.deepEqual(JSON.parse(originalBytes), f.original);
});
for (const outcome of ["failure", "success"]) {
  test(`generated empty fallback without errors recovers baseline failure after agent ${outcome}`, (t) => {
    const f = fixture(t);
    const placeholder = lock.jobs.agent.steps.find((step) => step.name === "Write agent output placeholder if missing");
    const fallback = /echo '([^']+)'/.exec(placeholder.run)[1];
    assert.deepEqual(JSON.parse(fallback), { items: [] });
    fs.writeFileSync(f.outputFile, fallback);
    f.write("baseline-exit-code.txt", "1");
    f.write("pre-repair-errors.txt", "error NU1301: HTTP401 restoring an implicit SDK pack");
    const { body, telemetry } = f.complete(outcome);
    assert.equal(telemetry.status, "failed");
    assert.match(body, /NoEngineResult/);
    assert.match(body, /NU1301.*HTTP401/);
    assert.equal(fs.existsSync(path.join(f.results, "result.json")), false);
    assert.equal(fs.existsSync(path.join(f.results, "engine-command.txt")), false);
  });
}
