for (const [name, setup] of [
  ["capability failure", (f) => f.write("engine-errors.txt", "Installed azsdk does not support --max-attempts")],
  ["process crash", (f) => { f.write("engine-stdout.txt", ""); f.write("engine-stderr.txt", "process crashed"); f.write("engine-exit-code.txt", "127"); }],
  ["malformed response", (f) => { f.engine(success); f.write("engine-stdout.txt", "not JSON"); }],
  ["contradictory response", (f) => f.engine(success, 1)],
  ["partial process evidence", (f) => f.write("engine-stdout.txt", JSON.stringify(success))],
  ["exceeded configured attempt bound", (f) => f.engine({ ...success, attemptsUsed: 4 })],
  ["stale success JSON", (f) => f.write("result.json", JSON.stringify(success))],
  ["green baseline with attempted engine", (f) => { f.write("baseline-exit-code.txt", "0"); f.write("engine-command.txt", "actual invocation"); }],
]) {
  test(`recovery fails closed for ${name}`, (t) => {
    const f = fixture(t);
    setup(f);
    const { body, telemetry } = f.complete();
    assert.equal(telemetry.status, "failed");
    assert.match(body, /\*\*Stop reason\*\* \| `NoEngineResult`/);
  });
}
