test("oversized recovered command remains lossless in the named repair-report artifact", (t) => {
  const f = fixture(t);
  f.engine(failed);
  const command = "azsdk " + "x".repeat(70000);
  f.write("engine-command.txt", command);
  const { body } = f.complete();
  assert(body.length <= 65000);
  assert.match(body, /`repair-report` artifact/);
  assert.equal(fs.readFileSync(path.join(f.results, "engine-command.txt"), "utf8"), command);
  assert(fs.readFileSync(path.join(f.results, "repair-report-full.md"), "utf8").includes(command));
});
